DROP TABLE IF EXISTS `email_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `email_templates` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` enum('LOAN_APPLICATION_SUBMITTED','LOAN_APPROVED','LOAN_REJECTED','PAYMENT_POSTED','SETTLEMENT_REQUESTED','SETTLEMENT_DECIDED','USER_CREATED','PASSWORD_RESET_OTP','PASSWORD_RESET_LINK') COLLATE utf8mb4_unicode_ci NOT NULL,
  `locale` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'lo',
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bodyHtml` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `bodyText` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `variables` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `isActive` tinyint NOT NULL DEFAULT '1',
  `updatedBy` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `IDX_984d2647909622ddd3ea6186f5` (`code`,`locale`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
