INSERT INTO `email_templates` VALUES ('012f2552-4ff6-4338-8bdf-50d5e22f9b9b','LOAN_APPLICATION_SUBMITTED','lo','เบฎเบฑเบเบเบณเบฎเปเบญเบเบชเบดเบเป€เบเบทเปเบญ {{loanCode}} เบฎเบฝเบเบฎเปเบญเบเปเบฅเปเบง','<div style=\"font-family:Segoe UI,Arial,sans-serif;background:#f4f6fa;padding:24px\"><div style=\"max-width:560px;margin:0 auto;background:#ffffff;border:1px solid #dfe3ec;border-radius:12px;overflow:hidden\"><div style=\"background:#1f3a8a;color:#ffffff;padding:18px 24px;font-size:17px;font-weight:600\">เบฎเบฑเบเบเบณเบฎเปเบญเบเบชเบดเบเป€เบเบทเปเบญ</div><div style=\"padding:24px;color:#33384a;font-size:14px;line-height:1.7\"><p>เบชเบฐเบเบฒเบเบ”เบต เบ—เปเบฒเบ{{recipientName}}</p><table style=\"width:100%;border-collapse:collapse;margin:16px 0\"><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เป€เบฅเบเบ—เบตเปเบชเบดเบเป€เบเบทเปเบญ</td><td style=\"padding:6px 0;font-weight:600\">{{loanCode}}</td></tr><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เบเบฐเบฅเบดเบ”เบ•เบฐเบเบฑเบ</td><td style=\"padding:6px 0;font-weight:600\">{{productName}}</td></tr><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เบเบณเบเบงเบเบเปเบเบนเป</td><td style=\"padding:6px 0;font-weight:600\">{{amount}}</td></tr><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เปเบฅเบเบฐเป€เบงเบฅเบฒ</td><td style=\"padding:6px 0;font-weight:600\">{{term}}</td></tr><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เบชเบฐเบ–เบฒเบเบฐ</td><td style=\"padding:6px 0;font-weight:600\">{{status}}</td></tr></table><p>เบ—เปเบฒเบเบเบฐเปเบ”เปเบฎเบฑเบเปเบเปเบเป€เบ•เบทเบญเบเบญเบตเบเบเบฑเปเบเป€เบกเบทเปเบญเบเบดเบเบฒเบฅเบฐเบเบฒเปเบฅเปเบง.</p></div><div style=\"padding:14px 24px;background:#f4f6fa;color:#6b7280;font-size:12px\">เบฅเบฐเบเบปเบเบเบฑเบ”เบเบฒเบเบชเบดเบเป€เบเบทเปเบญ</div></div></div>','เบฅเบฐเบเบปเบเบเบฑเบ”เบเบฒเบเบชเบดเบเป€เบเบทเปเบญ\nเบฎเบฑเบเบเบณเบฎเปเบญเบเบชเบดเบเป€เบเบทเปเบญ\n\nเป€เบฅเบเบ—เบตเปเบชเบดเบเป€เบเบทเปเบญ: {{loanCode}}\nเบเบฐเบฅเบดเบ”เบ•เบฐเบเบฑเบ: {{productName}}\nเบเบณเบเบงเบเบเปเบเบนเป: {{amount}}\nเปเบฅเบเบฐเป€เบงเบฅเบฒ: {{term}}\nเบชเบฐเบ–เบฒเบเบฐ: {{status}}\n\nเบ—เปเบฒเบเบเบฐเปเบ”เปเบฎเบฑเบเปเบเปเบเป€เบ•เบทเบญเบเบญเบตเบเบเบฑเปเบเป€เบกเบทเปเบญเบเบดเบเบฒเบฅเบฐเบเบฒเปเบฅเปเบง.','[\"recipientName\",\"loanCode\",\"productName\",\"amount\",\"term\",\"status\"]',1,NULL,'2026-10-12 14:53:35.222767','2026-10-12 14:53:35.222767'),('1ae2eb1b-eac4-46d3-a4f5-510552a2406b','SETTLEMENT_REQUESTED','lo','เบฎเบฑเบเบเบณเบฎเปเบญเบเบเบดเบ”เบเบฑเบเบเบต {{loanCode}} เบฎเบฝเบเบฎเปเบญเบเปเบฅเปเบง','<div style=\"font-family:Segoe UI,Arial,sans-serif;background:#f4f6fa;padding:24px\"><div style=\"max-width:560px;margin:0 auto;background:#ffffff;border:1px solid #dfe3ec;border-radius:12px;overflow:hidden\"><div style=\"background:#1f3a8a;color:#ffffff;padding:18px 24px;font-size:17px;font-weight:600\">เบฎเบฑเบเบเบณเบฎเปเบญเบเบเบดเบ”เบเบฑเบเบเบต</div><div style=\"padding:24px;color:#33384a;font-size:14px;line-height:1.7\"><p>เบชเบฐเบเบฒเบเบ”เบต เบ—เปเบฒเบ{{recipientName}}</p><table style=\"width:100%;border-collapse:collapse;margin:16px 0\"><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เป€เบฅเบเบ—เบตเปเบชเบดเบเป€เบเบทเปเบญ</td><td style=\"padding:6px 0;font-weight:600\">{{loanCode}}</td></tr><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เบเบณเบเบงเบเบ—เบตเปเบเปเบเบดเบ”</td><td style=\"padding:6px 0;font-weight:600\">{{settlementAmount}}</td></tr><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เบเบญเบ”เบเบปเบเป€เบซเบผเบทเบญเบฅเบงเบก</td><td style=\"padding:6px 0;font-weight:600\">{{totalOutstanding}}</td></tr><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เบชเปเบงเบเบฅเบปเบ”เบ—เบตเปเบเป</td><td style=\"padding:6px 0;font-weight:600\">{{waiverAmount}}</td></tr><tr><td style=\"padding:6px 0;color:#6b7280;width:45%\">เบชเบฐเบ–เบฒเบเบฐ</td><td style=\"padding:6px 0;font-weight:600\">{{status}}</td></tr></table><p>เบเบณเบฎเปเบญเบเบเบตเปเบเบฐเบ•เปเบญเบเบเปเบฒเบเบเบฒเบเบญเบฐเบเบธเบกเบฑเบ”เบ•เบฒเบกเบเบฑเปเบเบ•เบญเบเบญเบตเบเบเบฑเปเบ.</p></div><div style=\"padding:14px 24px;background:#f4f6fa;color:#6b7280;font-size:12px\">เบฅเบฐเบเบปเบเบเบฑเบ”เบเบฒเบเบชเบดเบเป€เบเบทเปเบญ</div></div></div>','เบฅเบฐเบเบปเบเบเบฑเบ”เบเบฒเบเบชเบดเบเป€เบเบทเปเบญ\nเบฎเบฑเบเบเบณเบฎเปเบญเบเบเบดเบ”เบเบฑเบเบเบต\n\nเป€เบฅเบเบ—เบตเปเบชเบดเบเป€เบเบทเปเบญ: {{loanCode}}\nเบเบณเบเบงเบเบ—เบตเปเบเปเบเบดเบ”: {{settlementAmount}}\nเบเบญเบ”เบเบปเบเป€เบซเบผเบทเบญเบฅเบงเบก: {{totalOutstanding}}\nเบชเปเบงเบเบฅเบปเบ”เบ—เบตเปเบเป: {{waiverAmount}}\nเบชเบฐเบ–เบฒเบเบฐ: {{status}}\n\nเบเบณเบฎเปเบญเบเบเบตเปเบเบฐเบ•เปเบญเบเบเปเบฒเบเบเบฒเบเบญเบฐเบเบธเบกเบฑเบ”เบ•เบฒเบกเบเบฑเปเบเบ•เบญเบเบญเบตเบเบเบฑเปเบ.','[\"recipientName\",\"loanCode\",\"settlementAmount\",\"totalOutstanding\",\"waiverAmount\",\"status\"]',1,NULL,'2026-10-12 14:53:35.275888','2026-10-12 14:53:35.275888'),('36fe5100-c39c-4022-bb66-9a3a18c430b2','PASSWORD_RESET_LINK','lo','เบฅเบดเปเบเบ•เบฑเปเบเบฅเบฐเบซเบฑเบ”เบเปเบฒเบเปเปเป เบชเบณเบฅเบฑเบ {{username}}','<div style=\"font-family:Segoe UI,Arial,sans-serif;background:#f4f6fa;padding:24px\"><div style=\"max-width:560px;margin:0 auto;background:#ffffff;border:1px solid #dfe3ec;border-radius:12px;overflow:hidden\"><div style=\"background:#1f3a8a;color:#ffffff;padding:18px 24px;font-size:17px;font-weight:600\">เบ•เบฑเปเบเบฅเบฐเบซเบฑเบ”เบเปเบฒเบเปเปเป</div><div style=\"padding:24px;color:#33384a;font-size:14px;line-height:1.7\"><p>เบชเบฐเบเบฒเบเบ”เบต เบ—เปเบฒเบ{{recipientName}}</p><p style=\"text-align:center;margin:20px 0\"><a href=\"{{resetUrl}}\" style=\"background:#1f3a8a;color:#ffffff;padding:12px 24px;border-radius:8px;text-decoration:none\">เบ•เบฑเปเบเบฅเบฐเบซเบฑเบ”เบเปเบฒเบเปเปเป</a></p><table style=\"width:100%;border-collapse:collapse;marg