--
-- Table structure for table `financial_transactions`
--

DROP TABLE IF EXISTS `financial_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `financial_transactions` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `referenceNo` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `transactionType` enum('DISBURSEMENT','PAYMENT','SETTLEMENT_PAYMENT','PAYMENT_REVERSAL','PENALTY','WAIVER','WRITE_OFF','WRITE_OFF_REVERSAL','ADJUSTMENT') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('DRAFT','PENDING_APPROVAL','APPROVED','POSTED','REJECTED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_APPROVAL',
  `loanId` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customerId` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(18,2) NOT NULL DEFAULT '0.00',
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LAK',
  `referenceTransactionId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sourceRequestId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `settlementAgreementId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `componentAmounts` text COLLATE utf8mb4_unicode_ci,
  `reason` text COLLATE utf8mb4_unicode_ci,
  `rejectionReason` text COLLATE utf8mb4_unicode_ci,
  `createdBy` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `postedBy` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approvedAt` datetime DEFAULT NULL,
  `postedAt` datetime DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `IDX_cd7841b25723906a1ec18022c0` (`referenceNo`),
  KEY `IDX_758b72045d828989a3e8b87028` (`referenceTransactionId`),
  KEY `IDX_5e1d060cfea925ab38f6edadbc` (`status`),
  KEY `IDX_b08ed80ae46318be4cce7ca099` (`customerId`),
  KEY `IDX_d6ec34143543be886131f8e339` (`loanId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

